#include <stdio.h>
#include "mxml.h"

static bool sax_cb(void *data, mxml_node_t *node, mxml_sax_event_t event)
{
  (void)data; (void)node;
  return event != MXML_SAX_EVENT_ELEMENT_CLOSE;
}

int main(void)
{
  mxml_options_t *opts = mxmlOptionsNew();
  mxmlOptionsSetSAXCallback(opts, sax_cb, NULL);
  mxml_node_t *root = mxmlLoadString(NULL, opts, "<a></a>");
  printf("root=%p\n", (void *)root);
  mxmlOptionsDelete(opts);
  return 0;
}

